"use client";

import { useState, useTransition, type ReactNode } from "react";
import { Button, buttonVariants } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { Textarea } from "@/components/ui/textarea";
import type { SubscriptionState } from "@/lib/subscription-state";
import {
  FOLLOW_UP_QUESTIONS,
  PAID_REASONS,
  TRIAL_REASONS,
  describeOffer,
  pickOffer,
  type CancelReason,
  type OfferPolicy,
  type SaveOffer,
} from "@/lib/cancel-offer";
import type { CancelRequest, CancelResult, RefundableCharge } from "@/lib/cancel-subscription";

// Reason, then one next step, then the cancellation. Within a day of a charge
// the next step is the money back; otherwise it is at most one save offer,
// with the same moves in the same order: talk to a person, take the offer, or
// cancel. "No thanks, cancel" is always visible and never a trick.

export interface CancelFlowProps {
  state: SubscriptionState;
  // True once this customer has accepted a save offer: `await offerUsed(stripe, customerId)`.
  offerUsed: boolean;
  // A charge recent enough to give back: `await refundableCharge(stripe, subscriptionId)`.
  refund?: RefundableCharge | null;
  // Your server action: authenticate, look up the user's subscription id, then
  // return `cancelSubscription(stripe, subscriptionId, request)`.
  action: (request: CancelRequest) => Promise<CancelResult>;
  policy?: OfferPolicy;
  // A booking link for a call with a real person, offered first.
  bookingUrl?: string;
  // Shown above the offer, for example a short founder video.
  media?: ReactNode;
  triggerLabel?: string;
  onDone?: (result: CancelResult) => void;
}

export function CancelFlow({
  state,
  offerUsed,
  refund = null,
  action,
  policy,
  bookingUrl,
  media,
  triggerLabel,
  onDone,
}: CancelFlowProps) {
  const isTrial = state === "trialing";
  const noun = isTrial ? "trial" : "subscription";
  const reasons: Record<string, string> = isTrial ? TRIAL_REASONS : PAID_REASONS;
  const [open, setOpen] = useState(false);
  const [step, setStep] = useState<"reason" | "refund" | "offer" | "done">("reason");
  const [reason, setReason] = useState<CancelReason | null>(null);
  const [followUp, setFollowUp] = useState("");
  const [comment, setComment] = useState("");
  const [result, setResult] = useState<CancelResult | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [pending, startTransition] = useTransition();
  const offer = reason ? pickOffer({ state, reason, offerUsed, policy }) : null;
  const followUpQuestion = reason ? FOLLOW_UP_QUESTIONS[reason] : undefined;
  // Whether another step follows, known before a reason is picked so the
  // button does not change its label under the customer's cursor.
  const nextStep = refund
    ? "refund"
    : pickOffer({ state, reason: reason ?? "other", offerUsed, policy })
      ? "offer"
      : null;

  function openChange(next: boolean) {
    setOpen(next);
    if (next) return;
    if (result) onDone?.(result);
    setStep("reason");
    setReason(null);
    setFollowUp("");
    setComment("");
    setResult(null);
    setError(null);
  }

  function submit(decision: CancelRequest["decision"]) {
    if (!reason) return;
    setError(null);
    startTransition(async () => {
      try {
        const next = await action({
          reason,
          followUp: followUpQuestion ? followUp : null,
          comment,
          decision,
        });
        if (next.outcome === "invalid") {
          setError(
            next.error === "refund_unavailable"
              ? "That charge can no longer be refunded here. You can still cancel."
              : "This subscription can't be changed right now. Refresh the page and try again.",
          );
          return;
        }
        setResult(next);
        setStep("done");
      } catch {
        setError("Something went wrong and nothing was changed. Please try again.");
      }
    });
  }

  const cancelLink = (label: string) => (
    <Button variant="ghost" disabled={pending} onClick={() => submit("cancel")}>
      {label}
    </Button>
  );
  const back = (
    <Button variant="ghost" disabled={pending} onClick={() => setStep("reason")}>
      Back
    </Button>
  );

  return (
    // No asChild or render props anywhere, so the same file works with the
    // Radix and the Base UI flavours of the shadcn primitives.
    <Dialog open={open} onOpenChange={openChange}>
      <Button variant="outline" onClick={() => setOpen(true)}>
        {triggerLabel ?? `Cancel ${noun}`}
      </Button>
      <DialogContent className="sm:max-w-lg">
        {step === "reason" && (
          <>
            <DialogHeader>
              <DialogTitle>Before you go, what&apos;s the main reason?</DialogTitle>
              <DialogDescription>One answer is enough.</DialogDescription>
            </DialogHeader>
            <RadioGroup
              value={reason ?? ""}
              onValueChange={(value: unknown) => setReason(value as CancelReason)}
              className="grid gap-2 sm:grid-cols-2"
            >
              {Object.entries(reasons).map(([value, label]) => (
                <Label
                  key={value}
                  htmlFor={`cancel-reason-${value}`}
                  className="flex cursor-pointer items-center gap-2.5 rounded-md border px-3 py-2.5 font-normal has-[[aria-checked=true]]:border-primary has-[[aria-checked=true]]:bg-accent"
                >
                  <RadioGroupItem id={`cancel-reason-${value}`} value={value} />
                  {label}
                </Label>
              ))}
            </RadioGroup>
            {followUpQuestion && (
              <div className="grid gap-1.5">
                <Label htmlFor="cancel-follow-up" className="text-muted-foreground font-normal">
                  {followUpQuestion} (optional)
                </Label>
                <Input
                  id="cancel-follow-up"
                  maxLength={200}
                  value={followUp}
                  onChange={(event) => setFollowUp(event.target.value)}
                />
              </div>
            )}
            <div className="grid gap-1.5">
              <Label htmlFor="cancel-comment" className="text-muted-foreground font-normal">
                What would have changed your mind? (optional)
              </Label>
              <Textarea
                id="cancel-comment"
                maxLength={500}
                rows={3}
                value={comment}
                onChange={(event) => setComment(event.target.value)}
              />
            </div>
            {error && <p className="text-destructive text-sm">{error}</p>}
            <DialogFooter className="sm:justify-between">
              <Button variant="ghost" onClick={() => openChange(false)}>
                Keep my {noun}
              </Button>
              {nextStep ? (
                <Button disabled={!reason} onClick={() => setStep(nextStep)}>
                  Continue
                </Button>
              ) : (
                <Button
                  variant="destructive"
                  disabled={!reason || pending}
                  onClick={() => submit("cancel")}
                >
                  Cancel my {noun}
                </Button>
              )}
            </DialogFooter>
          </>
        )}

        {step === "refund" && refund && (
          <>
            <DialogHeader>
              <DialogTitle>No problem, have it back</DialogTitle>
              <DialogDescription>
                You were charged {formatMoney(refund.amountCents, refund.currency)}{" "}
                {hoursAgo(refund.paidAt)}. Take a full refund now and your {noun} ends
                today.
              </DialogDescription>
            </DialogHeader>
            <Button disabled={pending} onClick={() => submit("refund")}>
              Refund {formatMoney(refund.amountCents, refund.currency)} and cancel
            </Button>
            {error && <p className="text-destructive text-sm">{error}</p>}
            <DialogFooter className="sm:justify-between">
              {cancelLink("Keep access until the period ends instead")}
              {back}
            </DialogFooter>
          </>
        )}

        {step === "offer" && offer && (
          <>
            <DialogHeader>
              <DialogTitle>{bookingUrl ? "Can we talk first?" : "Before you cancel"}</DialogTitle>
              <DialogDescription>{offerPitch(offer, Boolean(bookingUrl))}</DialogDescription>
            </DialogHeader>
            {media}
            <div className="flex flex-col gap-2 sm:flex-row">
              {bookingUrl && (
                <a href={bookingUrl} target="_blank" rel="noreferrer" className={buttonVariants()}>
                  Book a call
                </a>
              )}
              <Button
                variant={bookingUrl ? "outline" : "default"}
                disabled={pending}
                onClick={() => submit("accept_offer")}
              >
                {describeOffer(offer)}
              </Button>
            </div>
            {error && <p className="text-destructive text-sm">{error}</p>}
            <DialogFooter className="sm:justify-between">
              {cancelLink(`No thanks, cancel my ${noun}`)}
              {back}
            </DialogFooter>
          </>
        )}

        {step === "done" && result && (
          <>
            <DialogHeader>
              <DialogTitle>{doneTitle(result, noun)}</DialogTitle>
              <DialogDescription>{doneMessage(result, noun)}</DialogDescription>
            </DialogHeader>
            <DialogFooter>
              <Button onClick={() => openChange(false)}>Close</Button>
            </DialogFooter>
          </>
        )}
      </DialogContent>
    </Dialog>
  );
}

function formatMoney(cents: number, currency: string): string {
  return new Intl.NumberFormat(undefined, { style: "currency", currency }).format(cents / 100);
}

function hoursAgo(paidAt: Date): string {
  const hours = Math.floor((Date.now() - new Date(paidAt).getTime()) / 3_600_000);
  return hours < 1 ? "less than an hour ago" : hours === 1 ? "an hour ago" : `${hours} hours ago`;
}

function offerPitch(offer: SaveOffer, canCall: boolean): string {
  const call = canCall ? "A short call is the fastest way to fix what went wrong. Or: " : "";
  switch (offer.kind) {
    case "extend_trial":
      return `${call}take ${offer.days} more days, free. A short trial is rarely long enough to judge it.`;
    case "pause":
      return `${call}pause billing for ${offer.months === 1 ? "a month" : `${offer.months} months`}. Your account stays exactly as it is and picks up again on its own.`;
    case "waive_invoice":
      return `${call}keep your account and skip this month's payment, on us.`;
    case "discount":
      return offer.percentOff === 100
        ? `${call}take your next ${offer.months === 1 ? "month" : `${offer.months} months`} free, on us.`
        : `${call}take ${offer.percentOff}% off your next ${offer.months} months.`;
  }
}

function doneTitle(result: CancelResult, noun: string): string {
  if (result.outcome === "saved") return "Done, thank you for staying";
  if (result.outcome === "refunded") return "Refunded and cancelled";
  return `Your ${noun} is cancelled`;
}

function doneMessage(result: CancelResult, noun: string): string {
  if (result.outcome === "saved") {
    if (result.offer.kind === "pause") return "Billing is paused. Nothing else changes.";
    if (result.offer.kind === "waive_invoice") return "This month's payment is cancelled. Nothing else changes.";
    return "The offer is applied to your account.";
  }
  if (result.outcome === "refunded") {
    return `${formatMoney(result.amountCents, result.currency)} is on its way back. It usually reaches your card in 5 to 10 days.`;
  }
  if (result.outcome === "cancelled" && result.accessEndsAt) {
    const endsAt = new Date(result.accessEndsAt);
    const date = endsAt.toLocaleDateString(undefined, { month: "long", day: "numeric", year: "numeric" });
    return endsAt.getTime() <= Date.now() + 60_000
      ? `Your ${noun} has ended. You won't be charged again.`
      : `You keep full access until ${date}. You won't be charged again.`;
  }
  return "You won't be charged again.";
}

import type { SubscriptionState } from "@/lib/subscription-state";

// Which save offer a cancelling customer sees. Pure, so the page that renders
// the dialog and the server action that applies the decision pick the same
// offer from the same facts. The server always re-picks; the browser never
// tells it which offer was shown.
//
// One offer per customer, ever: a restarted subscription does not earn another.
// A trial is offered time, never money: a discount on a product someone has not
// used yet saves nobody. A paying customer is offered what their reason asks
// for. A customer whose renewal already failed gets that month forgiven: a
// coupon only discounts next month and would leave this one owed.

export const TRIAL_REASONS = {
  setup: "Couldn't get it set up",
  no_time: "Haven't had time to try it properly",
  no_results_yet: "Didn't see results yet",
  too_expensive: "Too expensive for me right now",
  not_expected: "Not what I expected",
  switched: "Switching to another tool",
  other: "Something else",
} as const;

export const PAID_REASONS = {
  no_results: "Not getting enough value",
  too_expensive: "Too expensive",
  pausing: "Pausing for now",
  switched: "Switching to another tool",
  missing_feature: "Missing a feature I need",
  hard_to_use: "Hard to set up or use",
  other: "Something else",
} as const;

export type CancelReason = keyof typeof TRIAL_REASONS | keyof typeof PAID_REASONS;

// The one follow-up question, asked only after these reasons. The answer is
// stored with the cancellation so you learn the price, the competitor or the
// missing feature, not just the category.
export const FOLLOW_UP_QUESTIONS: Partial<Record<CancelReason, string>> = {
  too_expensive: "What would you pay per month?",
  switched: "Which tool are you switching to?",
  missing_feature: "Which feature do you need?",
};

export type SaveOffer =
  | { kind: "extend_trial"; days: number }
  | { kind: "discount"; percentOff: number; months: number }
  | { kind: "pause"; months: number }
  | { kind: "waive_invoice" };

export interface OfferPolicy {
  trialExtensionDays: number;
  // A trial can never run longer than this many days in total, extensions included.
  maxTrialDays: number;
  discount: { percentOff: number; months: number };
  pauseMonths: number;
  // Cancelling within this many hours of a charge offers it back in full.
  refundWindowHours: number;
}

export const DEFAULT_OFFER_POLICY: OfferPolicy = {
  trialExtensionDays: 7,
  maxTrialDays: 14,
  discount: { percentOff: 50, months: 2 },
  pauseMonths: 1,
  refundWindowHours: 24,
};

export function isCancelReason(state: SubscriptionState, value: unknown): value is CancelReason {
  const reasons = state === "trialing" ? TRIAL_REASONS : PAID_REASONS;
  return typeof value === "string" && Object.hasOwn(reasons, value);
}

export function pickOffer(input: {
  state: SubscriptionState;
  reason: CancelReason;
  // True once this customer has accepted any save offer, on any subscription.
  offerUsed: boolean;
  policy?: OfferPolicy;
}): SaveOffer | null {
  const policy = input.policy ?? DEFAULT_OFFER_POLICY;
  if (input.offerUsed) return null;
  if (input.state === "trialing") {
    return { kind: "extend_trial", days: policy.trialExtensionDays };
  }
  if (input.state === "past_due") return { kind: "waive_invoice" };
  if (input.state !== "active") return null;
  if (input.reason === "pausing") return { kind: "pause", months: policy.pauseMonths };
  if (input.reason === "too_expensive") return { kind: "discount", ...policy.discount };
  // Everything else gets a free month: the time to fix what went wrong.
  return { kind: "discount", percentOff: 100, months: 1 };
}

// Adds the days to whatever is left of the trial, but never past the total cap
// counted from the trial's start.
export function extendedTrialEnd(
  subscription: { trial_start: number | null; trial_end: number | null },
  days: number,
  maxTrialDays: number,
  now: Date = new Date(),
): number {
  const nowSeconds = Math.floor(now.getTime() / 1000);
  const base = Math.max(subscription.trial_end ?? nowSeconds, nowSeconds);
  const wanted = base + days * 86_400;
  const cap = (subscription.trial_start ?? nowSeconds) + maxTrialDays * 86_400;
  return Math.max(base, Math.min(wanted, cap));
}

// Whether a charge paid at `paidAt` may still be refunded in the cancel flow.
export function isWithinRefundWindow(paidAt: Date, now: Date, windowHours: number): boolean {
  const age = now.getTime() - paidAt.getTime();
  return age >= 0 && age <= windowHours * 3_600_000;
}

export function describeOffer(offer: SaveOffer): string {
  switch (offer.kind) {
    case "waive_invoice":
      return "Take this month free";
    case "extend_trial":
      return `Add ${offer.days} days to my trial`;
    case "pause":
      return offer.months === 1 ? "Pause for a month instead" : `Pause for ${offer.months} months instead`;
    case "discount":
      if (offer.percentOff === 100) {
        return offer.months === 1 ? "Take next month free" : `Take ${offer.months} months free`;
      }
      return `Take ${offer.percentOff}% off for ${offer.months} months`;
  }
}

import "server-only";
import type Stripe from "stripe";
import { subscriptionState, canCancel } from "@/lib/subscription-state";
import {
  DEFAULT_OFFER_POLICY,
  extendedTrialEnd,
  isCancelReason,
  isWithinRefundWindow,
  pickOffer,
  type CancelReason,
  type OfferPolicy,
  type SaveOffer,
} from "@/lib/cancel-offer";

// The cancel flow's only server code. Call it from your own server action
// after you have authenticated the user and looked up THEIR subscription id;
// never take a subscription id from the browser.
//
// Everything is recorded on Stripe itself, so there is no table to migrate:
// the reason goes into Stripe's own `cancellation_details` and the offer shown,
// and what the customer did with it, into the subscription's metadata.
// Cancelling cancels here instead of sending people to the billing portal,
// where cancellations can silently fail to land.

export interface CancelRequest {
  reason: string;
  // The answer to the reason's follow-up question, if it has one.
  followUp?: string | null;
  comment?: string | null;
  decision: "accept_offer" | "refund" | "cancel";
}

export type CancelResult =
  | { outcome: "saved"; offer: SaveOffer }
  | { outcome: "refunded"; amountCents: number; currency: string }
  | { outcome: "cancelled"; accessEndsAt: Date | null }
  | {
      outcome: "invalid";
      error: "not_cancellable" | "invalid_reason" | "offer_unavailable" | "refund_unavailable";
    };

export interface RefundableCharge {
  amountCents: number;
  currency: string;
  paidAt: Date;
}

const METADATA = {
  shown: "retention_offer_shown",
  accepted: "retention_offer_accepted",
  coupon: "retention_offer_coupon",
  reason: "cancel_reason",
  followUp: "cancel_follow_up",
} as const;

// One save offer per customer, ever: a cancelled-and-restarted subscription
// does not earn a second one.
export async function offerUsed(stripe: Stripe, customerId: string): Promise<boolean> {
  for await (const subscription of stripe.subscriptions.list({ customer: customerId, status: "all" })) {
    if (subscription.metadata?.[METADATA.accepted]) return true;
  }
  return false;
}

export async function cancelSubscription(
  stripe: Stripe,
  subscriptionId: string,
  request: CancelRequest,
  policy: OfferPolicy = DEFAULT_OFFER_POLICY,
): Promise<CancelResult> {
  const subscription = await stripe.subscriptions.retrieve(subscriptionId);
  const state = subscriptionState(subscription);
  if (!canCancel(state)) return { outcome: "invalid", error: "not_cancellable" };
  if (!isCancelReason(state, request.reason)) return { outcome: "invalid", error: "invalid_reason" };
  const reason = request.reason;
  const followUp = request.followUp?.trim().slice(0, 200) || null;
  const comment = [followUp, request.comment?.trim()].filter(Boolean).join("\n").slice(0, 1000) || null;
  const customerId = typeof subscription.customer === "string" ? subscription.customer : subscription.customer.id;
  const offer = pickOffer({ state, reason, offerUsed: await offerUsed(stripe, customerId), policy });
  const shown = offer ? offerKey(offer) : null;
  const metadata = {
    ...(shown ? { [METADATA.shown]: shown } : {}),
    [METADATA.reason]: reason,
    ...(followUp ? { [METADATA.followUp]: followUp } : {}),
  };
  const details = { feedback: stripeFeedback(reason), ...(comment ? { comment } : {}) };

  if (request.decision === "accept_offer") {
    // Someone who clicked "accept" is never cancelled because the offer went
    // away in the meantime (used in another tab, or the subscription changed).
    if (!offer) return { outcome: "invalid", error: "offer_unavailable" };
    const params = await offerParams(stripe, subscription, offer, policy);
    await stripe.subscriptions.update(subscriptionId, {
      ...params.update,
      metadata: {
        ...metadata,
        [METADATA.accepted]: `${shown}@${new Date().toISOString()}`,
        ...(params.couponId ? { [METADATA.coupon]: params.couponId } : {}),
      },
    });
    return { outcome: "saved", offer };
  }

  if (request.decision === "refund") {
    // Rechecked here, so a stale page cannot refund an old charge.
    const charge = await latestPaidCharge(stripe, subscription);
    if (!charge || !isWithinRefundWindow(charge.paidAt, new Date(), policy.refundWindowHours)) {
      return { outcome: "invalid", error: "refund_unavailable" };
    }
    // One refund per payment, however many times the button is pressed.
    await stripe.refunds.create(
      { ...charge.target, reason: "requested_by_customer" },
      { idempotencyKey: `cancel-refund:${charge.paymentId}` },
    );
    // A refunded period keeps no access.
    await endNow(stripe, subscriptionId, metadata, details);
    return { outcome: "refunded", amountCents: charge.amountCents, currency: charge.currency };
  }

  // A failed payment is not a period to run out: void what it owes so Stripe
  // stops retrying the card, and end it now.
  if (state === "past_due") {
    await voidOpenInvoice(stripe, subscription);
    await endNow(stripe, subscriptionId, metadata, details);
    return { outcome: "cancelled", accessEndsAt: new Date() };
  }
  const updated = await stripe.subscriptions.update(subscriptionId, {
    cancel_at_period_end: true,
    cancellation_details: details,
    metadata,
    // A paused subscription that cancels must not stay paused forever.
    ...(state === "paused" ? { pause_collection: "" as const } : {}),
  });
  return {
    outcome: "cancelled",
    accessEndsAt: updated.cancel_at ? new Date(updated.cancel_at * 1000) : null,
  };
}

// The charge a cancelling customer may still get back, for the dialog's
// `refund` prop. Null when there is none inside the policy's window.
export async function refundableCharge(
  stripe: Stripe,
  subscriptionId: string,
  policy: OfferPolicy = DEFAULT_OFFER_POLICY,
): Promise<RefundableCharge | null> {
  const subscription = await stripe.subscriptions.retrieve(subscriptionId);
  if (!canCancel(subscriptionState(subscription))) return null;
  const charge = await latestPaidCharge(stripe, subscription);
  if (!charge || !isWithinRefundWindow(charge.paidAt, new Date(), policy.refundWindowHours)) return null;
  return { amountCents: charge.amountCents, currency: charge.currency, paidAt: charge.paidAt };
}

// Takes back a scheduled cancellation, for the "Keep my subscription" button a
// cancelling customer sees instead of the cancel flow. Clears both forms:
// this flow sets cancel_at_period_end, the Stripe portal may set cancel_at.
export async function resumeSubscription(stripe: Stripe, subscriptionId: string): Promise<void> {
  const subscription = await stripe.subscriptions.retrieve(subscriptionId);
  await stripe.subscriptions.update(
    subscriptionId,
    subscription.cancel_at_period_end ? { cancel_at_period_end: false } : { cancel_at: "" },
  );
}

// A customer who took a free month and cancelled before any invoice used it
// still has that month. Pass the returned coupon id to the Checkout session
// that restarts them; null when there is nothing to carry over. The original
// coupon is single-use, so a fresh one is created.
export async function unusedFreeMonthCoupon(
  stripe: Stripe,
  endedSubscriptionId: string,
): Promise<string | null> {
  const ended = await stripe.subscriptions.retrieve(endedSubscriptionId, { expand: ["discounts"] });
  const couponId = ended.metadata?.[METADATA.coupon];
  if (!couponId || !ended.metadata?.[METADATA.accepted]?.startsWith("discount_100pct_1m")) return null;
  // Stripe removes a once-coupon from the subscription when an invoice uses it.
  const stillAttached = (ended.discounts ?? []).some((discount) => {
    const coupon = typeof discount === "string" ? null : discount.source?.coupon;
    return (typeof coupon === "string" ? coupon : coupon?.id) === couponId;
  });
  if (!stillAttached) return null;
  return (await createSaveCoupon(stripe, 100, 1)).id;
}

async function offerParams(
  stripe: Stripe,
  subscription: Stripe.Subscription,
  offer: SaveOffer,
  policy: OfferPolicy,
): Promise<{ update: Stripe.SubscriptionUpdateParams; couponId?: string }> {
  switch (offer.kind) {
    case "extend_trial":
      return {
        update: {
          trial_end: extendedTrialEnd(subscription, offer.days, policy.maxTrialDays),
          proration_behavior: "none",
        },
      };
    case "pause": {
      const resumesAt = new Date();
      resumesAt.setMonth(resumesAt.getMonth() + offer.months);
      return {
        update: {
          pause_collection: { behavior: "void", resumes_at: Math.floor(resumesAt.getTime() / 1000) },
        },
      };
    }
    case "waive_invoice":
      // Voiding the failed invoice forgives this month and returns the
      // subscription to active; the next renewal bills as usual.
      await voidOpenInvoice(stripe, subscription);
      return { update: {} };
    case "discount": {
      const coupon = await createSaveCoupon(stripe, offer.percentOff, offer.months);
      return {
        update: { discounts: [...existingDiscounts(subscription), { coupon: coupon.id }] },
        couponId: coupon.id,
      };
    }
  }
}

// Ends the subscription now. A second request racing the first (another tab)
// finds it already ended and reports the same outcome instead of an error.
async function endNow(
  stripe: Stripe,
  subscriptionId: string,
  metadata: Record<string, string>,
  details: Stripe.SubscriptionCancelParams.CancellationDetails,
): Promise<void> {
  try {
    await stripe.subscriptions.update(subscriptionId, { metadata });
    await stripe.subscriptions.cancel(subscriptionId, { cancellation_details: details });
  } catch (error) {
    const current = await stripe.subscriptions.retrieve(subscriptionId);
    if (current.status !== "canceled") throw error;
  }
}

function createSaveCoupon(stripe: Stripe, percentOff: number, months: number) {
  return stripe.coupons.create({
    percent_off: percentOff,
    duration: months === 1 ? "once" : "repeating",
    ...(months === 1 ? {} : { duration_in_months: months }),
    max_redemptions: 1,
    name: `Save offer: ${percentOff}% off`,
  });
}

async function voidOpenInvoice(stripe: Stripe, subscription: Stripe.Subscription): Promise<void> {
  const invoiceId =
    typeof subscription.latest_invoice === "string" ? subscription.latest_invoice : subscription.latest_invoice?.id;
  if (!invoiceId) return;
  const invoice = await stripe.invoices.retrieve(invoiceId);
  if (invoice.status === "open") await stripe.invoices.voidInvoice(invoiceId);
}

// The latest invoice's successful payment, if it has not been refunded.
async function latestPaidCharge(stripe: Stripe, subscription: Stripe.Subscription) {
  const invoiceId =
    typeof subscription.latest_invoice === "string" ? subscription.latest_invoice : subscription.latest_invoice?.id;
  if (!invoiceId) return null;
  const invoice = await stripe.invoices.retrieve(invoiceId);
  const paidAt = invoice.status_transitions?.paid_at;
  if (invoice.status !== "paid" || !paidAt || invoice.amount_paid <= 0) return null;
  const payments = await stripe.invoicePayments.list({ invoice: invoiceId, status: "paid", limit: 1 });
  const payment = payments.data[0]?.payment;
  const intent = typeof payment?.payment_intent === "string" ? payment.payment_intent : payment?.payment_intent?.id;
  const chargeId = typeof payment?.charge === "string" ? payment.charge : payment?.charge?.id;
  const target = intent ? { payment_intent: intent } : chargeId ? { charge: chargeId } : null;
  if (!target) return null;
  const refunds = await stripe.refunds.list({ ...target, limit: 1 });
  if (refunds.data.length > 0) return null;
  return {
    target,
    paymentId: intent ?? chargeId!,
    amountCents: invoice.amount_paid,
    currency: invoice.currency,
    paidAt: new Date(paidAt * 1000),
  };
}

function existingDiscounts(subscription: Stripe.Subscription): Array<{ discount: string }> {
  return (subscription.discounts ?? []).map((discount) => ({
    discount: typeof discount === "string" ? discount : discount.id,
  }));
}

function offerKey(offer: SaveOffer): string {
  switch (offer.kind) {
    case "extend_trial":
      return `extend_trial_${offer.days}d`;
    case "pause":
      return `pause_${offer.months}m`;
    case "waive_invoice":
      return "waive_invoice";
    case "discount":
      return `discount_${offer.percentOff}pct_${offer.months}m`;
  }
}

// Stripe's own vocabulary, so the reason shows up in the Dashboard and in
// Stripe's churn reporting without any work on your side.
function stripeFeedback(
  reason: CancelReason,
): Stripe.SubscriptionUpdateParams.CancellationDetails.Feedback {
  switch (reason) {
    case "too_expensive":
      return "too_expensive";
    case "switched":
      return "switched_service";
    case "missing_feature":
      return "missing_features";
    case "hard_to_use":
    case "setup":
      return "too_complex";
    case "no_time":
    case "pausing":
      return "unused";
    case "no_results":
    case "no_results_yet":
    case "not_expected":
      return "low_quality";
    default:
      return "other";
  }
}
